:root {
  color-scheme: dark;
  --ink: #211e1a;
  --deep: #2a2520;
  --panel: #383029;
  --panel-light: #453b30;
  --edge: #71604a;
  --edge-light: #a38a62;
  --paper: #f0dfb8;
  --muted: #c0ad87;
  --sage: #91a16d;
  --gold: #e6b95e;
  --rust: #bd674a;
  --shadow: #15120f;
  font-family: "Pixelify Sans", monospace;
  font-synthesis: none;
}

* { box-sizing: border-box; }
html, body { width: 100%; height: 100%; margin: 0; overflow: hidden; }
body {
  color: var(--paper);
  background: var(--ink);
  font-family: "Pixelify Sans", monospace;
  font-size: 13px;
  image-rendering: pixelated;
}
button { color: inherit; font: inherit; }
button, .board-cell { -webkit-tap-highlight-color: transparent; }
.game-shell {
  width: 100%; height: 100vh; height: 100dvh; max-width: 1440px;
  margin: 0 auto; padding: 10px 18px 8px;
  display: grid; grid-template-rows: 48px minmax(205px,.84fr) minmax(300px,1.2fr) 20px;
  gap: 10px; overflow: hidden; background: var(--ink);
}
.topbar { display:flex; align-items:center; justify-content:space-between; min-width:0; }
.brand { display:flex; align-items:center; gap:10px; color:inherit; text-decoration:none; }
.brand-mark {
  width:40px; height:40px; display:grid; place-items:center;
  color:var(--ink); background:var(--gold); border:3px solid #f4d889;
  box-shadow:3px 3px 0 var(--shadow), inset 0 0 0 2px #c98d42;
  font-weight:700; font-size:16px; letter-spacing:-1px;
}
.brand b { display:block; color:var(--paper); font-size:17px; line-height:1; letter-spacing:1px; }
.brand small { display:block; margin-top:3px; color:var(--muted); font-size:10px; letter-spacing:1px; }
.top-meta { display:flex; align-items:center; gap:9px; }
.coin-pill {
  height:38px; min-width:110px; padding:3px 10px 3px 6px; display:grid;
  grid-template-columns:26px auto; grid-template-rows:18px 11px; align-items:center; column-gap:7px;
  background:#473824; border:2px solid #93764a; box-shadow:2px 2px 0 var(--shadow), inset 0 0 0 2px #30271d;
}
.coin-icon {
  grid-row:1/3; width:24px; height:24px; display:grid; place-items:center;
  background:var(--gold); border:2px solid #f5d477; color:#57401f; font-size:16px; font-weight:700;
  box-shadow:inset -2px -2px 0 #b77c36;
}
