.upgrade-list { display:grid; grid-template-columns:1fr 1fr; gap:12px 16px; padding-top:12px; }
.upgrade-group h3 { margin:0 0 5px; color:#d2c68d; font-size:13px; letter-spacing:.5px; }
.upgrade-row { display:grid; grid-template-columns:32px minmax(0,1fr) auto; align-items:center; gap:7px; min-height:50px; border-top:2px solid #544636; padding:6px 0; }
