.upgrade-icon img { width:24px; height:24px; object-fit:contain; image-rendering:pixelated; }
.upgrade-pixel { display:block; width:24px; height:30px; background-image:url("assets/pixel/sprites.png"); background-repeat:no-repeat; background-size:600% 200%; background-position:0 0; image-rendering:pixelated; }
.upgrade-copy b { display:block; color:#f2e8cb; font-size:14px; line-height:1.2; }
