.buy-button span { font-size:11px; }
.buy-button:disabled { background:#524a3e; border-color:#70634e; color:#a4977a; box-shadow:none; cursor:not-allowed; }
.artist-slots { display:flex; align-items:center; justify-content:center; gap:5px; flex:1; min-width:0; padding:0 8px; overflow:hidden; }
.artist-slot {
  height:38px; min-width:42px; max-width:76px; flex:1 1 54px; display:flex; flex-direction:column;
  align-items:center; justify-content:center; gap:1px; padding:2px 3px; overflow:hidden;
  background:#40392e; border:2px solid #81704d; color:#e2d09e;
  box-shadow:2px 2px 0 #17130f, inset 0 -3px 0 #302920; cursor:pointer; touch-action:none;
