}
@media (max-width:760px) and (orientation:landscape) and (max-height:520px) {
  .game-shell { grid-template-columns:minmax(210px,.82fr) minmax(0,1.18fr); grid-template-rows:35px minmax(0,1fr); gap:6px; padding:5px; }
