257:   .upgrade-row { grid-template-columns:27px minmax(0,1fr) auto; gap:5px; min-height:45px; }
258:   .upgrade-icon { width:25px; height:25px; font-size:15px; }
259:   .buy-button { min-width:53px; padding:4px; font-size:10px; }
260: }
261: @media (max-width:390px) {
262:   .game-shell { grid-template-rows:37px minmax(158px,.65fr) minmax(0,1.35fr); gap:5px; padding:5px; }
263:   .brand b { font-size:12px; }
264:   .brand-mark { width:30px; height:30px; }
265:   .top-meta { gap:4px; }
266:   .upgrade-open, .lang-button { padding:0 5px; font-size:9px; }
267:   .coin-pill { min-width:74px; }
268:   .scene-wrap { min-height:65px; }
269:   .scene-heading h1 { font-size:16px; }
270:   .panel { padding:6px; }
271:   .board-cell .tool { width:32px; height:32px; }
272:   .merge-board { gap:3px; }
273:   .hint { margin:3px 0 4px; }
274:   .spawn-meter { width:30px; }
275:   .spawn-copy small { font-size:8px; }
276:   .artist-summary { flex-basis:78px; grid-template-columns:24px auto; }
277:   .artist-slots { gap:2px; padding:0 1px; }
278:   .artist-slot { min-width:22px; }
279:   .artist-slot small { font-size:7px; }
280:   .earnings { flex-basis:52px; }
281: }
282: @media (max-height:650px) and (min-width:761px) {
283:   .game-shell { grid-template-rows:40px minmax(160px,.72fr) minmax(250px,1.28fr) 16px; gap:6px; padding-top:6px; padding-bottom:5px; }
284:   .scene-wrap { min-height:72px; }
285:   .scene-heading h1 { font-size:19px; }
286:   .artist-strip { height:34px; flex-basis:34px; }
287:   .panel { padding:7px 9px; }
288:   .hint { margin:3px 0 5px; }
289:   .board-frame { padding:4px; }
290:   .merge-board { gap:4px; }
291:   .board-cell .tool { width:34px; height:34px; }
292:   .spawn-row { height:28px; flex-basis:28px; }
293:   .item-legend { min-height:18px; }
294:   .side-column { gap:5px; }
295: }
296: @media (max-width:760px) and (orientation:landscape) and (max-height:520px) {
297:   .game-shell { grid-template-columns:minmax(210px,.82fr) minmax(0,1.18fr); grid-template-rows:35px minmax(0,1fr); gap:6px; padding:5px; }
298:   .topbar { grid-column:1/-1; }
299:   .workshop-card { grid-column:1; grid-row:2; }
300:   .content-grid { grid-column:2; grid-row:2; }
301:   .scene-heading { min-height:23px; }
302:   .scene-wrap { min-height:40px; }
303:   .artist-strip { height:30px; flex-basis:30px; }
304:   .artist-summary small { display:none; }
305:   .artist-summary { grid-template-rows:22px; flex-basis:78px; }
306:   .artist-slot { height:27px; min-width:22px; }
307:   .artist-slot img { width:12px; height:12px; }
308:   .artist-slot .slot-plus { font-size:13px; line-height:13px; }
309:   .artist-slot small { font-size:6px; }
310:   .artist-slots { gap:2px; }
311:   .earnings { flex-basis:52px; }
312:   .board-cell .tool { width:28px; height:28px; }
313:   .hint { display:none; }
314:   .board-frame { padding:3px; }
315:   .spawn-row { height:25px; flex-basis:25px; }
316:   .item-legend { display:none; }
317: }

